templates.Breadcrumb:
"use client"

import type { ComponentProps as PlaygroundComponentProps } from "react"
import { Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbList, BreadcrumbPage, BreadcrumbSeparator } from "@/components/ui/breadcrumb";

const playgroundProps: Partial<PlaygroundComponentProps<typeof Breadcrumb>> = /*__DS_PROPS__*/ {}


export function BreadcrumbDemo() {
  return (
    <Breadcrumb>{playgroundProps.children ?? <>
      <BreadcrumbList>
        <BreadcrumbItem>
          <BreadcrumbLink href="#">Home</BreadcrumbLink>
        </BreadcrumbItem>
        <BreadcrumbSeparator />
        <BreadcrumbItem>
          <BreadcrumbPage>Components</BreadcrumbPage>
        </BreadcrumbItem>
      </BreadcrumbList>
    </>}</Breadcrumb>
  )
}

